    title: 'Senior Partner',
    practice: 'Family Law',
  },
  {
    initials: 'JW',
    name: 'Jane White',
    title: 'Partner',
    practice: 'Criminal Law',
  },
  {
    initials: 'SM',
    name: 'Steve Matthews',
    title: 'Partner',
    practice: 'Business Law',
  },
];

const AttorneyCard = ({ initials, name, title, practice }) => (
  <div className="bg-white border-slate-200 rounded-xl shadow-md p-6 flex flex-col items-center text-center">
    <div className="rounded-full bg-slate-200 w-20 h-20 flex items-center justify-center mb-4 text-4xl">
      <span className="text-slate-600">{initials}</span>
    </div>
    <h3 className="text-slate-900 text-xl mb-1">{name}</h3>
    <p className="text-slate-600 mb-2">{title}</p>
    <p className="text-slate-600">{practice}</p>
    <button className="bg-blue-900 hover:bg-blue-950 text-white rounded-xl px-4 py-2 mt-4">
      Book a Call
    </button>
  </div>
);

const Attorneys = () => (
  <section className="bg-white py-20">
    <div className="max-w-6xl mx-auto px-6">
      <h2 className="text-slate-900 text-4xl font-display font-bold mb-10 text-center">Our Attorneys</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
        {attorneys.map((attorney, i) => (
          <AttorneyCard key={i} {...attorney} />
        ))}
      </div>
    </div>
  </section>
);

export default Attorneys;

import React, { useState } from "react";

const Faq = () => {
  const [activeFaq, setActiveFaq] = useState(null);

  const faqs = [
    {
      question: "What is your return policy?",
      answer: "Our return policy is simple: if you're not 100% satisfied with your purchase, we'll give you a full refund within 30 days of receiving your item. If you're not fully satisfied, just let us know and we'll do our best to help you.",
    },
    // Add more FAQs as needed
  ];

  return (
    <section className="bg-slate-50 pt-20 pb-12 px-6 max-w-6xl mx-auto">
      <h2 className="text-slate-900 font-display text-4xl mb-8">FAQ</h2>
      <div className="flex flex-col gap-8">
        {faqs.map((faq, index) => (
          <div
            key={index}
            className={`border-slate-200 border-l-4 p-6 rounded-xl ${
              activeFaq === index ? "bg-white" : "bg-slate-50"
            }`}
          >
            <button
              className="flex justify-between items-start w-full"
              onClick={() =>
                activeFaq === index ? setActiveFaq(null) : setActiveFaq(index)
              }
            >
              <h3 className="text-slate-900 font-medium text-lg">
                {faq.question}
              </h3>
              <span
                className={`transition-transform duration-300 ${
                  activeFaq === index ? "rotate-180" : ""
                }`}
              >
                ➔
              </span>
            </button>
            <p
              className={`mt-4 text-slate-600 ${
                activeFaq !== index ? "hidden" : ""
              }`}
            >
              {faq.answer}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

export default Faq;

